// app/Sources/ProjectDocument+GraphicFiles.swift — deleting, renaming and
// restoring a module of the document's `graphics/` (spec §11 G-27, G-28,
// G-29; issue #103): the three bodies BOTH doors call — the agent's
// `delete_graphic`, `rename_graphic` and `restore_graphic`
// (`AgentServer+GraphicFiles.swift`) and File ▸ Delete Graphic…, Rename
// Graphic… and Restore Graphic Version… — so the two refuse in the same
// sentences, and the repair that keeps a clip's module name and the file
// together across Undo.
//
// **Every throw of a body's own is a `ReelCoreError`**, its message the
// sentence. The "used" and "drawn" refusals are written here and are not a
// core rule's: each names a file act's precondition.
//
// **A file act is not an undo step and never dirties the document** (G-3):
// only a rename's `set_graphic` ops are model state, applied through the
// caller's `apply` as ONE step. Each body ends its file act in one
// `rescan()`, so it is called from a handler or a command — never from a
// `.graphicsDidChange` or `.projectGraphicsDidChange` observer (`drain()`
// is not re-entrant). Fonts and assets are never touched.

import AppKit
import CryptoKit

extension ProjectDocument {
    /// The clips drawn by the module `name`, one group per container that
    /// holds any: the timeline first (`nest` nil), then the nests by id; ids
    /// ascending. Reads the DOCUMENT, whatever nest is open.
    func graphicClips(named name: String) -> [(nest: UInt32?, clips: [UInt32])] {
        let snapshot = project.snapshot
        func drawn(_ clips: [ClipSnapshot]) -> [UInt32] {
            clips.filter { $0.graphic?.name == name }.map(\.id).sorted()
        }
        var groups: [(nest: UInt32?, clips: [UInt32])] = []
        let timeline = drawn(snapshot.clips)
        if !timeline.isEmpty { groups.append((nil, timeline)) }
        for nest in snapshot.nests.sorted(by: { $0.id < $1.id }) {
            let inside = drawn(nest.clips)
            if !inside.isEmpty { groups.append((nest.id, inside)) }
        }
        return groups
    }

    /// `clips 4 and 9 on the timeline and clip 12 in nest 7`: one group per
    /// container, joined by " and " (G-27 (b)).
    static func graphicClipSentence(_ groups: [(nest: UInt32?, clips: [UInt32])]) -> String {
        groups.map { group in
            let ids = group.clips.map { String($0) }
            let listed = ids.count == 1
                ? "clip \(ids[0])"
                : "clips " + ids.dropLast().joined(separator: ", ") + " and " + ids[ids.count - 1]
            return listed + (group.nest.map { " in nest \($0)" } ?? " on the timeline")
        }.joined(separator: " and ")
    }

    /// Deletes `graphics/<name>.js`, keeping its text (G-27); the kept
    /// revision. Refused while a clip draws the module.
    func deleteGraphic(named name: String) throws -> String {
        let store = try graphicFilesStore()
        guard store.module(named: name) != nil else {
            throw ReelCoreError(message: store.noModuleSentence(name))
        }
        let groups = graphicClips(named: name)
        guard groups.isEmpty else {
            throw ReelCoreError(
                message: "The graphic \"\(name)\" is still drawn by "
                    + Self.graphicClipSentence(groups) + Self.graphicClipAdvice)
        }
        let revision: String
        do {
            revision = try store.removeModule(named: name)
        } catch {
            throw Self.graphicFileFailure(name, "deleted", error)
        }
        store.rescan()
        return revision
    }

    /// Renames the module `name` to `to` (G-28): the file, its kept
    /// revisions, and every clip that names it — `apply` is handed one
    /// `set_graphic {name}` per container, each addressed to its own, to
    /// commit as ONE undo step, and is not called when no clip names the
    /// module. The ids repointed, ascending. When `apply` throws, or leaves
    /// a clip behind, the file is moved back and the journal put back as it
    /// was read before the rename: a refused rename journals no pair (G-28
    /// (d)). A move back that fails leaves the pair, for the repair.
    func renameGraphic(
        named name: String, to: String, apply: ([ReelOp]) throws -> Void
    ) throws -> [UInt32] {
        let store = try graphicFilesStore()
        guard store.module(named: name) != nil else {
            throw ReelCoreError(message: store.noModuleSentence(name))
        }
        guard GraphicStore.isModuleName(to) else {
            throw ReelCoreError(message: GraphicStore.nameSentence(to))
        }
        guard !store.holdsModule(named: to) else {
            throw ReelCoreError(message: "graphics/\(to).js already exists")
        }
        let drawn = graphicClips(named: to)
        guard drawn.isEmpty else {
            throw ReelCoreError(
                message: "The name \"\(to)\" is already drawn by "
                    + Self.graphicClipSentence(drawn) + Self.graphicClipAdvice)
        }
        if let nest = scope {
            throw ReelCoreError(
                message: "rename_graphic has no meaning inside nest \(nest): it renames the "
                    + "module for every clip in the project, the timeline's included. "
                    + "set_scope with no arguments comes back out; then rename.")
        }
        let journalled = GraphicStore.renameJournalBytes(in: store.folderURL)
        do {
            try store.moveModule(from: name, to: to)
        } catch {
            throw Self.graphicFileFailure(name, "renamed", error)
        }
        store.rescan()
        let groups = graphicClips(named: name)
        guard !groups.isEmpty else { return [] }
        let ops = groups.map {
            ReelOp.setGraphicRaw(clips: $0.clips, patch: ["name": to]).scoped($0.nest)
        }
        func moveBack() {
            if (try? store.moveModule(from: to, to: name)) != nil {
                GraphicStore.putBackRenameJournal(journalled, in: store.folderURL)
            }
            store.rescan()
        }
        do {
            try apply(ops)
        } catch {
            moveBack()
            throw error
        }
        guard graphicClips(named: name).isEmpty else {
            moveBack()
            throw ReelCoreError(
                message: "graphics/\(name).js could not be renamed: its clips did not take "
                    + "the new name")
        }
        return groups.flatMap { $0.clips }.sorted()
    }

    /// Writes a kept text of `name` back as `graphics/<name>.js` (G-29):
    /// `revision`, else the newest kept; the revision restored. The text it
    /// replaces is kept by the rescan's pass. Works when the file is absent.
    /// A kept file whose bytes are not the revision in its name is not a
    /// kept text (spec §5.6): refused, nothing written (G-29 (d)).
    func restoreGraphic(named name: String, revision: String?) throws -> String {
        let store = try graphicFilesStore()
        let kept = store.kept(named: name)
        guard var entry = kept.first else {
            throw ReelCoreError(
                message: "No kept revision of \"\(name)\" — one is kept when a write replaces "
                    + "a module's text or delete_graphic removes it")
        }
        if let revision = revision {
            guard let asked = kept.first(where: { $0.revision == revision }) else {
                let listed = kept.map(\.revision).joined(separator: ", ")
                throw ReelCoreError(
                    message: "\"\(name)\" has no kept revision \(revision) — kept: \(listed)")
            }
            entry = asked
        }
        do {
            let bytes = try Data(contentsOf: entry.url)
            guard GraphicStore.hex(SHA256.hash(data: bytes)) == entry.revision else {
                let others = kept.filter { $0 != entry }.map(\.revision)
                throw ReelCoreError(
                    message: "graphics/history/\(name)/\(entry.url.lastPathComponent) was "
                        + "changed outside Frame Job and no longer holds the revision in its "
                        + "name; it is not restored — other kept revisions: "
                        + (others.isEmpty ? "none" : others.joined(separator: ", ")))
            }
            try store.write(name: name, bytes: bytes)
        } catch let error as ReelCoreError {
            throw error
        } catch {
            throw Self.graphicFileFailure(name, "written", error)
        }
        store.rescan()
        return entry.revision
    }

    /// The repair (G-28 (e)), in ONE direction: a journalled pair says the
    /// app last moved the file FROM its first name TO its second, and for
    /// each pair, newest first, when the first name is drawn by a clip, has
    /// no file and has no kept revision, while the second has a file and no
    /// clip, the file is moved back under the first — which journals the
    /// pair the other way round, so Redo is the same repair. One `rescan()`
    /// if anything moved. Never from a pair's first name to its second: a
    /// drawn second name with no file is a removal the app did not make
    /// (G-28 (f)). A file-less name WITH kept revisions is a deleted module
    /// (G-27 (f)) and is left alone. Returns at once when every drawn name
    /// has a file.
    func reconcileGraphicNames() {
        guard let store = graphicStore else { return }
        let snapshot = project.snapshot
        let drawn = Set(
            (snapshot.clips + snapshot.nests.flatMap { $0.clips })
                .compactMap { $0.graphic?.name }.filter(GraphicStore.isModuleName))
        guard drawn.contains(where: { !store.holdsModule(named: $0) }) else { return }
        let folder = store.folderURL
        func onDisk(_ name: String) -> Bool {
            FileManager.default.fileExists(atPath: folder.appendingPathComponent(name + ".js").path)
        }
        var moved = false
        for (x, y) in store.renamePairs() {
            guard drawn.contains(x), !onDisk(x),
                store.kept(named: x).isEmpty,
                GraphicStore.isModuleName(y), onDisk(y), !drawn.contains(y),
                (try? store.moveModule(from: y, to: x)) != nil
            else { continue }
            moved = true
        }
        if moved { store.rescan() }
    }

    /// `.projectDocumentDidChange` for this document: every committed change
    /// (an edit, an undo, a redo), never a live gesture's tick.
    @objc func graphicNamesMayHaveChanged(_ note: Notification) {
        guard note.userInfo?["isLive"] as? Bool != true else { return }
        reconcileGraphicNames()
    }

    // MARK: - Sentences

    private static let graphicClipAdvice =
        "; delete those clips or point them at another module (set_graphic {name}) first"

    private func graphicFilesStore() throws -> GraphicStore {
        guard let store = graphicStore else {
            throw ReelCoreError(
                message: "This project has no graphics folder open (its window has not been made)")
        }
        return store
    }

    /// `graphics/<name>.js could not be <verb>: <why>`.
    private static func graphicFileFailure(
        _ name: String, _ verb: String, _ error: Error
    ) -> ReelCoreError {
        ReelCoreError(
            message: "graphics/\(name).js could not be \(verb): \(error.localizedDescription)")
    }
}
// app/Sources/GraphicStore+Import.swift — a font or a picture copied into
// `graphics/fonts/` or `graphics/assets/` (road map 10 §5h, G4b; G5b): the
// ONE body behind the agent's `import_graphic_font` and
// `import_graphic_asset` and a person's File ▸ Add Font to Graphics… and
// Add Image to Graphics…, so the two doors refuse in the same sentences.
//
// It goes through `ensureFolder()`, the ONE creator of `graphics/` inside a
// package (G-14), and lands the file the way `write(name:source:)` lands a
// module: a `<name>.partial` beside it, then moved into place, so the scan
// never reads half a file (a `.partial`'s extension is in neither the font
// nor the asset set, so it is never listed). `importFile` does not rescan;
// `importFont` and `importAsset` end in ONE `rescan()`, so the registry has
// its new library when they return — both are called from a handler or a
// command, never from a `.graphicsDidChange` observer (`drain()` is not
// re-entrant).
//
// **A font's family names are the ENGINE's own** (`rc_graphic_library_families`):
// the file is loaded into a throwaway library of its own and that library is
// asked, so `families` is exactly what a `font-family` must say — CoreText
// names some files differently (road map 10 §10.7 G4b measured 13 of 2500).
// Not undoable and never dirty (G-3).
//
// **An asset's name is one `asset(name)` can use** (spec §11 G-23): a name
// that is not is legalised (`GraphicAssetName`) and the copy filed under it,
// taking `-2`, `-3`, … while that name is held (scan or disk), so a RENAMED
// copy never replaces; the answer says the name used and the name asked for.
//
// **`landNew` is the `.fjgraphic` import's write** (spec §11 G-47 (e)): bytes
// already read, landed the same way but NEVER replacing — a file already at
// the name is a throw — and no rescan, which the import does once at its end.

import Foundation

extension GraphicStore {
    /// Copies `source` to `graphics/<subfolder>/<name>`, replacing a file of
    /// that name. Whether one was replaced. Main.
    func importFile(from source: URL, into subfolder: String, as name: String) throws
        -> (url: URL, replaced: Bool)
    {
        try ensureFolder()
        let files = FileManager.default
        let folder = folderURL.appendingPathComponent(subfolder, isDirectory: true)
        try files.createDirectory(at: folder, withIntermediateDirectories: true)
        let target = folder.appendingPathComponent(name)
        let replaced = try Self.land(at: target) { try files.copyItem(at: source, to: $0) }
        return (target, replaced)
    }

    /// `bytes` written to `graphics/<subfolder>/<name>` through a `.partial` beside it, never
    /// replacing: throws when a file is already there. Does not rescan. Main.
    func landNew(_ bytes: Data, into subfolder: String, as name: String) throws -> URL {
        try ensureFolder()
        let files = FileManager.default
        let folder = folderURL.appendingPathComponent(subfolder, isDirectory: true)
        try files.createDirectory(at: folder, withIntermediateDirectories: true)
        let target = folder.appendingPathComponent(name)
        guard !files.fileExists(atPath: target.path) else {
            throw ReelCoreError(message: "graphics/\(subfolder)/\(name) already exists")
        }
        let partial = folder.appendingPathComponent(name + ".partial")
        try? files.removeItem(at: partial)
        do {
            try bytes.write(to: partial)
            // `moveItem` refuses an existing target, so a file that appeared meanwhile stays.
            try files.moveItem(at: partial, to: target)
        } catch {
            try? files.removeItem(at: partial)
            throw error
        }
        return target
    }

    /// What `graphics/assets/` takes, in the refusals' words.
    static let assetKinds = "PNG, JPEG, GIF, WebP, SVG or SVGZ"

    /// A `.ttf` or `.otf` copied into `graphics/fonts/` under its own name,
    /// then `rescan()`. The families are the engine's reading of that file
    /// alone. Main.
    func importFont(from source: URL) throws -> (url: URL, replaced: Bool, families: [String]) {
        let path = source.path
        guard Self.fontExtensions.contains(source.pathExtension.lowercased()) else {
            throw ReelCoreError(message: "\(path) is not a .ttf or .otf file")
        }
        let bytes: Data
        do {
            bytes = try Data(contentsOf: source)
        } catch {
            throw ReelCoreError(
                message: "\(path) could not be read: \(error.localizedDescription)")
        }
        let probe = GraphicLibrary()
        do {
            try probe.addFont(bytes)
        } catch let error as ReelCoreError {
            throw ReelCoreError(message: "\(path): " + error.message)
        }
        let families = probe.families()
        let landed = try importNamed(source, Self.fontsFolderName, source.lastPathComponent)
        rescan()
        return (landed.url, landed.replaced, families)
    }

    /// A picture copied into `graphics/assets/<name>`, then `rescan()`.
    /// `name` is what `asset(name)` says; its extension must be one of the
    /// six. A name `asset(name)` cannot use is filed under a legal one
    /// (`renamedFrom` is the name asked for), never replacing a file. Main.
    func importAsset(from source: URL, as name: String) throws
        -> (url: URL, name: String, replaced: Bool, bytes: Int, renamedFrom: String?)
    {
        let path = source.path
        let kinds = Self.assetKinds
        guard !name.isEmpty, !name.contains("/") else {
            throw ReelCoreError(
                message: "name must be a file name with no / (got \"\(name)\") — it is what "
                    + "asset(name) says")
        }
        guard Self.assetExtensions.contains((name as NSString).pathExtension.lowercased())
        else {
            throw ReelCoreError(
                message: "\(name) is not a \(kinds) file (.png .jpg .jpeg .gif .webp .svg .svgz)")
        }
        let size = (try? FileManager.default.attributesOfItem(atPath: source.path)[.size]
            as? NSNumber)?.intValue ?? 0
        // An empty file crosses the FFI as NULL and the scan skips it.
        guard size > 0 else {
            throw ReelCoreError(
                message: "\(path) is empty (0 bytes) — an asset must hold a \(kinds) image")
        }
        let legal = GraphicAssetName.legalized(name)
        var used = legal
        if legal != name {
            var n = 2
            while holdsAsset(named: used) {
                used = GraphicAssetName.withSuffix(legal, n)
                n += 1
            }
        }
        let landed = try importNamed(source, Self.assetsFolderName, used)
        rescan()
        return (landed.url, used, landed.replaced, size, used == name ? nil : name)
    }

    /// True when the scan lists `name` or `graphics/assets/<name>` is on disk.
    func holdsAsset(named name: String) -> Bool {
        scan.assets.contains { $0.name == name }
            || FileManager.default.fileExists(
                atPath: folderURL.appendingPathComponent(Self.assetsFolderName, isDirectory: true)
                    .appendingPathComponent(name).path)
    }

    /// `importFile`, its failure said in a sentence naming the folder.
    private func importNamed(_ source: URL, _ subfolder: String, _ name: String) throws
        -> (url: URL, replaced: Bool)
    {
        do {
            return try importFile(from: source, into: subfolder, as: name)
        } catch {
            throw ReelCoreError(
                message: "graphics/\(subfolder)/\(name) could not be written: "
                    + error.localizedDescription)
        }
    }
}
// app/Sources/GraphicStore+Files.swift — the store's own writes into
// `graphics/`: the free-name rule and the module write (road map 10 §5f).
//
// **A name is taken when the scan holds it OR its file is on disk**, so a
// module written from the shell a moment before is never overwritten by a
// stale scan (#75). **A file lands through `land(at:writing:)`**: a
// `.partial` beside it, then moved into place, and on any failure the
// `.partial` is removed. `removeScratchRoot()` removes the untitled root
// (spec §11 G-19 (d)).
//
// **`removeModule` and `moveModule` are the app's delete and rename** (spec
// §11 G-27, G-28), each inside `onQueue` so no pass runs between their
// steps: the first keeps the file's bytes and then removes it, the second
// moves the file, journals the pair and moves its history, and a throw
// part-way leaves the file, the history and the journal where they were.
// Neither rescans.

import CryptoKit
import Foundation

extension GraphicStore {
    /// `base` when no module of that name is held, else `base-2`,
    /// `base-3`, … — `base` cut to 60 scalars first, so a suffix fits.
    func uniqueModuleName(_ base: String) -> String {
        let root = String(String.UnicodeScalarView(base.unicodeScalars.prefix(60)))
        guard holdsModule(named: root) else { return root }
        var n = 2
        while holdsModule(named: "\(root)-\(n)") { n += 1 }
        return "\(root)-\(n)"
    }

    /// True when the scan holds `name` or `<name>.js` is on disk.
    func holdsModule(named name: String) -> Bool {
        scan.modules[name] != nil
            || FileManager.default.fileExists(
                atPath: folderURL.appendingPathComponent(name + ".js").path)
    }

    /// The app's own write: `<name>.js.partial`, then moved into place, so
    /// a reader never sees half a module.
    func write(name: String, source: String) throws {
        try write(name: name, bytes: Data(source.utf8))
    }

    /// `write(name:source:)` for bytes as they are — a kept revision put
    /// back byte for byte.
    func write(name: String, bytes: Data) throws {
        guard Self.isModuleName(name) else { throw ReelCoreError(message: Self.nameSentence(name)) }
        try ensureFolder()
        writeManual()
        _ = try Self.land(at: folderURL.appendingPathComponent(name + ".js")) {
            try bytes.write(to: $0)
        }
    }

    /// Main. Keeps `<name>.js`'s bytes as its newest kept text, then
    /// removes the file; the kept revision. The caller rescans. A file whose
    /// text could not be kept is not removed (G-27 (c)).
    func removeModule(named name: String) throws -> String {
        try onQueue {
            let url = folderURL.appendingPathComponent(name + ".js")
            let bytes = try Data(contentsOf: url)
            let revision = Self.hex(SHA256.hash(data: bytes))
            Self.keep(bytes, named: name, in: folderURL)
            guard kept(named: name).first?.revision == revision else {
                throw ReelCoreError(
                    message: "its text could not be kept in graphics/"
                        + "\(Self.historyFolderName)/\(name)/")
            }
            do {
                try FileManager.default.removeItem(at: url)
            } catch {
                Self.dropKept(revision: revision, named: name, in: folderURL)
                throw error
            }
            return revision
        }
    }

    /// Main. Moves `<from>.js` to `<to>.js`, journals the pair, and moves
    /// its history with it; a throw leaves the file, the history and the
    /// journal where they were. **A rename that could not be journalled is
    /// refused** (G-28 (d)): the pair is written, and read back, before the
    /// history is folded — a fold cannot be undone — so no rename succeeds
    /// that Undo could not repair. When the history then fails to move, the
    /// journal is put back as it was read (its bytes, or no file): a
    /// refused rename journals no pair, and an earlier pair of the same two
    /// names is still there for Undo. A crash between the three steps is
    /// G-28 (f)'s limit. The caller checks the names and rescans.
    func moveModule(from: String, to: String) throws {
        try onQueue {
            let files = FileManager.default
            let source = folderURL.appendingPathComponent(from + ".js")
            let target = folderURL.appendingPathComponent(to + ".js")
            let journalled = Self.renameJournalBytes(in: folderURL)
            try files.moveItem(at: source, to: target)
            Self.recordRename(from, to, in: folderURL)
            guard let newest = renamePairs().first, newest == (from, to) else {
                try? files.moveItem(at: target, to: source)
                throw ReelCoreError(
                    message: "its rename could not be journalled in graphics/"
                        + "\(Self.historyFolderName)/\(Self.renameJournalName)")
            }
            do {
                try Self.moveHistory(from: from, to: to, in: folderURL)
            } catch {
                try? files.moveItem(at: target, to: source)
                Self.putBackRenameJournal(journalled, in: folderURL)
                throw error
            }
        }
    }

    /// The sentence for a module the folder does not hold, naming what it does.
    func noModuleSentence(_ name: String) -> String {
        let held = scan.modules.keys.sorted()
        let listed = held.isEmpty ? "nothing" : held.joined(separator: ", ")
        return "No module named \"\(name)\" in graphics/ — the folder holds: \(listed)"
    }

    /// Writes `<target>.partial` through `write` (any stale one removed
    /// first), then replaces `target` with it, or moves it into place when
    /// there is none. On any throw the partial is removed and the error
    /// rethrown. Whether it replaced.
    static func land(at target: URL, writing write: (URL) throws -> Void) throws -> Bool {
        let files = FileManager.default
        let partial = target.deletingLastPathComponent()
            .appendingPathComponent(target.lastPathComponent + ".partial")
        try? files.removeItem(at: partial)
        do {
            try write(partial)
            if files.fileExists(atPath: target.path) {
                _ = try files.replaceItemAt(target, withItemAt: partial)
                return true
            }
            try files.moveItem(at: partial, to: target)
            return false
        } catch {
            try? files.removeItem(at: partial)
            throw error
        }
    }

    /// Main, after `stop()`: the untitled root is removed; a package's
    /// `graphics/` is never touched (G-14, G-19 (d)).
    func removeScratchRoot() {
        guard package == nil else { return }
        try? FileManager.default.removeItem(at: folderURL)
    }
}

