190	// app/Sources/GraphicPackageImport.swift — a `.fjgraphic` copied into a
191	// project's `graphics/` (spec §11 G-47): what the package holds, where each
192	// file goes, the copy, and what it answers. No UI: the sheet
193	// (`GraphicImportSheetController.swift`) and `import_graphic`
194	// (`AgentServer+GraphicImports.swift`) both call these bodies, so the two
195	// doors refuse in the same sentences.
196	//
197	// **The checks** (G-47 (c)) are the core's first — `ReelGraphicPackage.read`,
198	// the archive and its manifest — then the app's: a font must load in a
199	// throwaway library, as `importFont` does, and an asset must be a name
200	// `asset(name)` can use. Every refusal is "<file name> cannot be imported:
201	// <sentence>", and none writes anything.
202	//
203	// **The plan** (G-47 (d)) puts each file under the manifest's name: written
204	// when the name is free, reused when the file there holds the same bytes;
205	// otherwise a module or a font takes `-2`, `-3`, … and an asset refuses the
206	// import, because the module reaches it by name. A name is matched exactly:
207	// one that differs only in case is another file, and is never free.
208	//
209	// **The copy** (G-47 (e)) writes the fonts, then the assets, with
210	// `landNew` (never replacing), then the module with `write(name:bytes:)`; a
211	// throw removes every file it wrote, rescans and rethrows. One `rescan()` at
212	// the end, from the caller's handler or command — never from a
213	// `.graphicsDidChange` observer. Not undoable and never dirty (G-3).
214	
215	import Foundation
216	
217	/// One font or asset of a package, under the manifest's `name`.
218	struct GraphicPackageFile {
219	    let name: String
220	    let bytes: Data
221	}
