223	/// A package read and checked, ready to plan.
224	struct GraphicPackageContents {
225	    let module: String
226	    let title: String
227	    let category: String
228	    let description: String?
229	    let appVersion: String
230	    let source: Data
231	    let fonts: [GraphicPackageFile]
232	    let assets: [GraphicPackageFile]
233	
234	    /// Reads the file at `url` and checks it, the core's checks then the app's.
235	    static func read(at url: URL) throws -> GraphicPackageContents {
236	        let refuse = { (sentence: String) in
237	            ReelCoreError(message: "\(url.lastPathComponent) cannot be imported: \(sentence)")
238	        }
239	        let values = try? url.resourceValues(forKeys: [.isRegularFileKey, .fileSizeKey])
240	        guard values?.isRegularFile == true else { throw refuse("it is not a file") }
241	        let size = values?.fileSize ?? 0
242	        guard size > 0 else { throw refuse("it is empty (0 bytes)") }
243	        guard UInt64(size) <= UInt64(UInt32.max) else {
244	            throw refuse("it is \(size) bytes, more than a .fjgraphic holds (\(UInt32.max))")
245	        }
246	        let data: Data
247	        do {
248	            data = try Data(contentsOf: url)
249	        } catch {
250	            throw refuse("it could not be read: \(error.localizedDescription)")
251	        }
252	        let answer: String
253	        do {
254	            answer = try ReelGraphicPackage.read(data)
255	        } catch let error as ReelCoreError {
256	            throw refuse(error.message)
257	        }
258	        guard let manifest = (try? JSONSerialization.jsonObject(with: Data(answer.utf8)))
259	            as? [String: Any], let files = manifest["files"] as? [[String: Any]],
260	            let first = files.first
261	        else { throw refuse("the core's answer could not be read") }
262	        func bytes(_ file: [String: Any]) -> Data {
263	            let offset = file["offset"] as? Int ?? 0, length = file["size"] as? Int ?? 0
264	            return data.subdata(in: offset..<(offset + length))
265	        }
266	        var fonts: [GraphicPackageFile] = [], assets: [GraphicPackageFile] = []
267	        for file in files.dropFirst() {
268	            let entry = GraphicPackageFile(name: file["name"] as? String ?? "", bytes: bytes(file))
269	            let path = file["path"] as? String ?? ""
270	            if path.hasPrefix(GraphicStore.fontsFolderName + "/") {
271	                fonts.append(entry)
272	            } else {
273	                assets.append(entry)
274	            }
275	        }
276	        for font in fonts {
277	            let ext = (font.name as NSString).pathExtension.lowercased()
278	            guard GraphicStore.fontExtensions.contains(ext) else {
279	                throw refuse("the font \"\(font.name)\" is not a .ttf or .otf file")
280	            }
281	            do {
282	                try GraphicLibrary().addFont(font.bytes)
283	            } catch let error as ReelCoreError {
284	                throw refuse("the font \"\(font.name)\": \(error.message)")
285	            }
286	        }
287	        for asset in assets {
288	            let ext = (asset.name as NSString).pathExtension.lowercased()
289	            guard GraphicStore.assetExtensions.contains(ext) else {
290	                throw refuse(
291	                    "the picture \"\(asset.name)\" is not a \(GraphicStore.assetKinds) file")
292	            }
293	            guard GraphicAssetName.isLegal(asset.name) else {
294	                throw refuse("the picture \"\(asset.name)\" \(GraphicAssetName.rule)")
295	            }
296	            guard !asset.bytes.isEmpty else {
297	                throw refuse("the picture \"\(asset.name)\" is empty (0 bytes)")
298	            }
299	        }
300	        return GraphicPackageContents(
301	            module: manifest["module"] as? String ?? "", title: manifest["title"] as? String ?? "",
302	            category: manifest["category"] as? String ?? "",
303	            description: manifest["description"] as? String,
304	            appVersion: manifest["app_version"] as? String ?? "", source: bytes(first),
305	            fonts: fonts, assets: assets)
306	    }
307	}
