321	/// Where every file of a package goes in one project, and the copy.
322	struct GraphicImportPlan {
323	    let contents: GraphicPackageContents
324	    let module: GraphicImportPlacement
325	    let fonts: [GraphicImportPlacement]
326	    let assets: [GraphicImportPlacement]
327	
328	    /// G-47 (d) over the store's scan and the disk. Throws, writing nothing, for an asset
329	    /// whose name holds a different picture, or with no store.
330	    static func make(_ contents: GraphicPackageContents, document: ProjectDocument) throws
331	        -> GraphicImportPlan
332	    {
333	        guard let store = document.graphicStore else {
334	            throw ReelCoreError(message: ProjectDocument.noGraphicsFolderSentence)
335	        }
336	        let folder = store.folderURL
337	        let free = { (name: String) in
338	            !store.holdsModule(named: name) && document.graphicClips(named: name).isEmpty
339	        }
340	        let module: GraphicImportPlacement
341	        let held = try? Data(contentsOf: folder.appendingPathComponent(contents.module + ".js"))
342	        if free(contents.module) {
343	            module = .init(name: contents.module, target: contents.module, action: .written)
344	        } else if held == contents.source {
345	            module = .init(name: contents.module, target: contents.module, action: .reused)
346	        } else {
347	            let root = String(String.UnicodeScalarView(contents.module.unicodeScalars.prefix(60)))
348	            var n = 2
349	            while !free("\(root)-\(n)") { n += 1 }
350	            module = .init(name: contents.module, target: "\(root)-\(n)", action: .written)
351	        }
352	        var fonts = Names(folder.appendingPathComponent(GraphicStore.fontsFolderName))
353	        let fontPlaces = contents.fonts.map { font -> GraphicImportPlacement in
354	            var target = font.name
355	            var n = 2
356	            while true {
357	                if let action = fonts.place(target, font.bytes) {
358	                    return .init(name: font.name, target: target, action: action)
359	                }
360	                target = GraphicAssetName.withSuffix(font.name, n)
361	                n += 1
362	            }
363	        }
364	        var assets = Names(folder.appendingPathComponent(GraphicStore.assetsFolderName))
365	        let assetPlaces = try contents.assets.map { asset -> GraphicImportPlacement in
366	            guard let action = assets.place(asset.name, asset.bytes) else {
367	                throw ReelCoreError(
368	                    message: "graphics/assets/\(asset.name) already holds a different picture, "
369	                        + "and this graphic reaches its own by asset(\"\(asset.name)\"), so it "
370	                        + "cannot be renamed; rename or remove the project's file and import "
371	                        + "again")
372	            }
373	            return .init(name: asset.name, target: asset.name, action: action)
374	        }
375	        return GraphicImportPlan(
376	            contents: contents, module: module, fonts: fontPlaces, assets: assetPlaces)
377	    }
378	
379	    /// One folder's names, as the disk holds them and as this plan claims them.
380	    private struct Names {
381	        let folder: URL
382	        var taken: [String]
383	
384	        init(_ folder: URL) {
385	            self.folder = folder
386	            taken = (try? FileManager.default.contentsOfDirectory(atPath: folder.path)) ?? []
387	        }
388	
389	        /// `.written` when `name` is free (and claims it), `.reused` when a file of exactly
390	        /// that name holds `bytes`, nil otherwise — a name that differs only in case is taken.
391	        mutating func place(_ name: String, _ bytes: Data) -> GraphicImportAction? {
392	            let url = folder.appendingPathComponent(name)
393	            if taken.contains(name) {
394	                return (try? Data(contentsOf: url)) == bytes ? .reused : nil
395	            }
396	            let folded = name.lowercased()
397	            guard !taken.contains(where: { $0.lowercased() == folded }),
398	                !FileManager.default.fileExists(atPath: url.path)
399	            else { return nil }
400	            taken.append(name)
401	            return .written
402	        }
403	    }
404	
405	    /// The copy: fonts, assets, then the module, none replacing a file; a throw removes what
406	    /// it wrote and rescans. One `rescan()` at the end. Main.
407	    func apply(to store: GraphicStore) throws {
408	        var written: [URL] = []
409	        var current = ""
410	        do {
411	            try store.ensureFolder()
412	            for (folder, places, files) in [
413	                (GraphicStore.fontsFolderName, fonts, contents.fonts),
414	                (GraphicStore.assetsFolderName, assets, contents.assets),
415	            ] {
416	                for (place, file) in zip(places, files) where place.action == .written {
417	                    current = "\(folder)/\(place.target)"
418	                    written.append(try store.landNew(file.bytes, into: folder, as: place.target))
419	                }
420	            }
421	            if module.action == .written {
422	                current = "\(module.target).js"
423	                try store.write(name: module.target, bytes: contents.source)
424	            }
425	        } catch {
426	            for url in written { try? FileManager.default.removeItem(at: url) }
427	            store.rescan()
428	            let why = (error as? ReelCoreError)?.message ?? error.localizedDescription
429	            throw ReelCoreError(message: "graphics/\(current) could not be written: \(why)")
430	        }
431	        store.rescan()
432	    }
433	
434	    /// `Imported <title> as <module>. Added: …. Already here: ….`
435	    var sentence: String {
436	        let all = [("\(module.target).js", module.action)]
437	            + fonts.map { ("\(GraphicStore.fontsFolderName)/\($0.target)", $0.action) }
438	            + assets.map { ("\(GraphicStore.assetsFolderName)/\($0.target)", $0.action) }
439	        var text = "Imported \(contents.title) as \(module.target)."
440	        for (label, action) in [("Added", GraphicImportAction.written), ("Already here", .reused)] {
441	            let names = all.filter { $0.1 == action }.map(\.0)
442	            if !names.isEmpty { text += " \(label): " + names.joined(separator: ", ") + "." }
443	        }
444	        return text
445	    }
446	
447	    /// `import_graphic`'s answer (spec §11 G-47 (i)).
448	    var reply: [String: Any] {
449	        var out: [String: Any] = [
450	            "name": module.target, "title": contents.title, "module": module.action.rawValue,
451	            "fonts": fonts.map { font -> [String: Any] in
452	                var row: [String: Any] = ["name": font.target, "action": font.action.rawValue]
453	                if font.target != font.name { row["renamed_from"] = font.name }
454	                return row
455	            },
456	            "assets": assets.map { ["name": $0.target, "action": $0.action.rawValue] },
457	            "note": AgentServer.notUndoableNote,
458	        ]
459	        if module.target != module.name { out["renamed_from"] = module.name }
460	        return out
461	    }
462	}
