475	// app/Sources/GraphicPackage.swift — the Graphic dialog's Export… and
476	// `export_graphic` (spec §11 G-46): one graphic written as a `.fjgraphic`
477	// package holding its module and only the project fonts and assets the
478	// engine saw it use.
479	//
480	// **A job is built on main and written off it.** `GraphicPackageJob.project`
481	// and `.template` read the document on main: the module's bytes, its title,
482	// category and description (`GraphicCatalog`), its size and length
483	// (`AgentServer.metaWhole`, as `render_graphic` reads them), and a FRESH
484	// library (`GraphicStore.makeIndexedLibrary()`; a template's holds the
485	// bundled faces alone). `write(to:)` runs QuickJS, so it runs only on the
486	// sheet's 8 MiB `Thread` or the agent's server thread — never main, never GCD.
487	//
488	// **The usage rule** (G-46 (b)): the module is compiled against that library
489	// and drawn — every frame up to `maxFrames` with its default props, else
490	// `maxFrames` evenly spaced, each `svg` then `rasterize` — and then each
491	// variant (an `enum` option other than the default, a boolean's opposite, in
492	// schema order, at most `maxVariants`) over `variantFrames` evenly spaced
493	// frames, every other prop at its default. The library's `usage()` is then
494	// every project font blob and asset to pack; a bundled face never is. A
495	// frame that throws is skipped and counted.
496	//
497	// **The file** is the core's (`ReelGraphicPackage.write`): written as
498	// `.<file>.partial` beside the destination and renamed over it, so an
499	// existing file is replaced whole; any throw removes the partial file.
500	
501	import Foundation
502	import UniformTypeIdentifiers
503	
504	enum GraphicPackage {
505	    static let fileExtension = "fjgraphic", typeIdentifier = "com.kgalligan.framejob-graphic"
506	    static let maxFrames = 900, variantFrames = 30, maxVariants = 32
507	
508	    /// The exported type (`project.yml`), else data by its extension (spec §11 G-47 (g)).
509	    static var contentType: UTType {
510	        UTType(typeIdentifier)
511	            ?? UTType(filenameExtension: fileExtension, conformingTo: .data) ?? .data
512	    }
513	
514	    /// The manifest's `app_version`: the bundle's `CFBundleShortVersionString`, else "".
515	    static var appVersion: String {
516	        Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? ""
517	    }
518	
519	    /// Every frame of `length` when there are at most `cap`, else `cap` frames evenly spaced
520	    /// from the first to the last.
521	    static func sampledFrames(length: Int, cap: Int) -> [Int] {
522	        guard length > cap else { return Array(0..<max(length, 0)) }
523	        guard cap > 1 else { return cap == 1 ? [0] : [] }
524	        return (0..<cap).map { i in
525	            Int((Double(i) * Double(length - 1) / Double(cap - 1)).rounded())
526	        }
527	    }
528	
529	    /// The props of each variant G-46 (b) draws: one per `enum` option other than its
530	    /// default and one per boolean's opposite, in schema order, at most `maxVariants`.
531	    static func variants(_ schema: GraphicSchema) -> [[String: Any]] {
532	        var out: [[String: Any]] = []
533	        for entry in schema.entries {
534	            switch (entry.type, entry.default) {
535	            case ("enum", let value):
536	                let current: String? = { if case .string(let s) = value { return s }; return nil }()
537	                for option in entry.options where option != current {
538	                    out.append([entry.key: option])
539	                }
540	            case ("boolean", .bool(let flag)):
541	                out.append([entry.key: !flag])
542	            default:
543	                continue
544	            }
545	        }
546	        return Array(out.prefix(maxVariants))
547	    }
548	}
