        var kept = sorted.prefix { $0.t < next }
        if kept.isEmpty {
            let first = sorted[0].t
            kept = sorted.prefix { $0.t == first }
            let after = sorted.first { $0.t > first }?.t
            return (Array(kept), after)
        }
        return (Array(kept), next)
    }

